import { mulberry32, randInt, type Rng } from "./rng.js";

export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface Room extends Rect {
  /** Center of the room (floor coordinates). */
  cx: number;
  cy: number;
}

export class BspNode {
  left?: BspNode;
  right?: BspNode;
  room?: Room;

  constructor(public readonly rect: Rect) {}

  get isLeaf(): boolean {
    return this.left === undefined && this.right === undefined;
  }

  leaves(): BspNode[] {
    if (this.isLeaf) return [this];
    return [...(this.left?.leaves() ?? []), ...(this.right?.leaves() ?? [])];
  }

  rooms(): Room[] {
    return this.leaves()
      .map((l) => l.room)
      .filter((r): r is Room => r !== undefined);
  }
}

export interface BspOptions {
  width: number;
  height: number;
  minLeafSize: number;
  minRatio: number;
  maxRatio: number;
  margin: number;
}

export const DEFAULT_OPTIONS: BspOptions = {
  width: 64,
  height: 48,
  minLeafSize: 10,
  minRatio: 0.35,
  maxRatio: 0.65,
  margin: 2,
};

export interface Dungeon {
  root: BspNode;
  rooms: Room[];
  width: number;
  height: number;
  /** Row-major tile grid; true = floor, false = wall. */
  tiles: Uint8Array;
}

function contains(outer: Rect, inner: Rect): boolean {
  return (
    inner.x >= outer.x &&
    inner.y >= outer.y &&
    inner.x + inner.w <= outer.x + outer.w &&
    inner.y + inner.h <= outer.y + outer.h
  );
}

/** Recursively split `node` until no axis can host two children of >= minLeafSize. */
function splitNode(node: BspNode, rng: Rng, opts: BspOptions): void {
  const { w, h } = node.rect;
  const min = opts.minLeafSize;
  const canSplitH = h >= 2 * min;
  const canSplitV = w >= 2 * min;
  if (!canSplitH && !canSplitV) return;

  // Split the longer axis; tie-break randomly.
  const horizontal = canSplitH
    ? !canSplitV || h > w || (h === w && rng() < 0.5)
    : false;

  const dim = horizontal ? node.rect.h : node.rect.w;
  const ratio = opts.minRatio + rng() * (opts.maxRatio - opts.minRatio);
  let cut = Math.round(dim * ratio);
  // Clamp so both children respect the minimum leaf size.
  cut = Math.min(Math.max(cut, min), dim - min);

  const a: Rect = horizontal
    ? { x: node.rect.x, y: node.rect.y, w, h: cut }
    : { x: node.rect.x, y: node.rect.y, w: cut, h };
  const b: Rect = horizontal
    ? { x: node.rect.x, y: node.rect.y + cut, w, h: dim - cut }
    : { x: node.rect.x + cut, y: node.rect.y, w: dim - cut, h };

  node.left = new BspNode(a);
  node.right = new BspNode(b);
  splitNode(node.left, rng, opts);
  splitNode(node.right, rng, opts);
}

/** Place one room per leaf, inset by `margin` from every leaf edge. */
function placeRooms(node: BspNode, rng: Rng, opts: BspOptions): void {
  if (!node.isLeaf) {
    placeRooms(node.left!, rng, opts);
    placeRooms(node.right!, rng, opts);
    return;
  }
  const innerW = node.rect.w - 2 * opts.margin;
  const innerH = node.rect.h - 2 * opts.margin;
  const w = randInt(rng, Math.min(3, innerW), innerW);
  const h = randInt(rng, Math.min(3, innerH), innerH);
  const x = node.rect.x + opts.margin + randInt(rng, 0, innerW - w);
  const y = node.rect.y + opts.margin + randInt(rng, 0, innerH - h);
  node.room = { x, y, w, h, cx: x + (w >> 1), cy: y + (h >> 1) };
}

/** Pick a deterministic pseudo-random room from a subtree. */
function pickRoom(node: BspNode, rng: Rng): Room {
  const leaves = node.leaves();
  return leaves[randInt(rng, 0, leaves.length - 1)].room!;
}

function carveCorridor(
  tiles: Uint8Array,
  width: number,
  from: Room,
  to: Room,
  rng: Rng,
): void {
  const set = (x: number, y: number) => {
    tiles[y * width + x] = 1;
  };
  let x = from.cx;
  let y = from.cy;
  const horizontalFirst = rng() < 0.5 || from.cy === to.cy;
  if (horizontalFirst) {
    while (x !== to.cx) {
      x += Math.sign(to.cx - x);
      set(x, y);
    }
    while (y !== to.cy) {
      y += Math.sign(to.cy - y);
      set(x, y);
    }
  } else {
    while (y !== to.cy) {
      y += Math.sign(to.cy - y);
      set(x, y);
    }
    while (x !== to.cx) {
      x += Math.sign(to.cx - x);
      set(x, y);
    }
  }
}

/**
 * Connect sibling regions with corridors between room centers.
 * Recursion unwinds up the tree, so every leaf ends up in one connected graph.
 */
function connectSiblings(
  node: BspNode,
  tiles: Uint8Array,
  width: number,
  rng: Rng,
): void {
  if (node.isLeaf) return;
  connectSiblings(node.left!, tiles, width, rng);
  connectSiblings(node.right!, tiles, width, rng);
  const a = pickRoom(node.left!, rng);
  const b = pickRoom(node.right!, rng);
  carveCorridor(tiles, width, a, b, rng);
}

export function generateDungeon(seed: number, options: Partial<BspOptions> = {}): Dungeon {
  const opts = { ...DEFAULT_OPTIONS, ...options };
  const rng = mulberry32(seed);

  const root = new BspNode({ x: 0, y: 0, w: opts.width, h: opts.height });
  splitNode(root, rng, opts);
  placeRooms(root, rng, opts);

  const tiles = new Uint8Array(opts.width * opts.height); // 0 = wall
  for (const room of root.rooms()) {
    for (let y = room.y; y < room.y + room.h; y++) {
      for (let x = room.x; x < room.x + room.w; x++) {
        tiles[y * opts.width + x] = 1;
      }
    }
  }
  connectSiblings(root, tiles, opts.width, rng);

  return { root, rooms: root.rooms(), width: opts.width, height: opts.height, tiles };
}

/** FNV-1a hash of the tile map, as 8 hex chars — used for determinism checks. */
export function hashTiles(dungeon: Dungeon): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < dungeon.tiles.length; i++) {
    h ^= dungeon.tiles[i]!;
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}

export function overlaps(a: Rect, b: Rect): boolean {
  return (
    a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h
  );
}

export function floodFillFloorCount(dungeon: Dungeon): number {
  const { width, height, tiles } = dungeon;
  const seen = new Uint8Array(width * height);
  const start = tiles.indexOf(1);
  if (start === -1) return 0;
  const queue = [start];
  seen[start] = 1;
  let count = 0;
  while (queue.length > 0) {
    const idx = queue.pop()!;
    count++;
    const x = idx % width;
    const y = (idx / width) | 0;
    for (const [dx, dy] of [
      [1, 0],
      [-1, 0],
      [0, 1],
      [0, -1],
    ] as const) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
      const nIdx = ny * width + nx;
      if (tiles[nIdx] === 1 && !seen[nIdx]) {
        seen[nIdx] = 1;
        queue.push(nIdx);
      }
    }
  }
  return count;
}

export function totalFloors(dungeon: Dungeon): number {
  let n = 0;
  for (let i = 0; i < dungeon.tiles.length; i++) n += dungeon.tiles[i]!;
  return n;
}

export { contains as rectContains };

export function renderAscii(dungeon: Dungeon): string {
  const rows: string[] = [];
  for (let y = 0; y < dungeon.height; y++) {
    let row = "";
    for (let x = 0; x < dungeon.width; x++) {
      row += dungeon.tiles[y * dungeon.width + x] ? "." : "#";
    }
    rows.push(row);
  }
  return rows.join("\n");
}

