import { describe, expect, it } from "vitest";
import {
  DEFAULT_OPTIONS,
  floodFillFloorCount,
  generateDungeon,
  hashTiles,
  overlaps,
  rectContains,
  totalFloors,
  type Dungeon,
} from "../src/bsp.js";

const SEEDS = Array.from({ length: 12 }, (_, i) => i + 1);

function roomRect(room: { x: number; y: number; w: number; h: number }) {
  return { x: room.x, y: room.y, w: room.w, h: room.h };
}

describe("BSP dungeon generator (seeds 1..12)", () => {
  const dungeons = new Map<number, Dungeon>(SEEDS.map((s) => [s, generateDungeon(s)]));

  it("produces a 64x48 map", () => {
    for (const d of dungeons.values()) {
      expect(d.width).toBe(64);
      expect(d.height).toBe(48);
      expect(d.tiles.length).toBe(64 * 48);
    }
  });

  it("every room fits inside its own leaf", () => {
    for (const d of dungeons.values()) {
      const leaves = d.root.leaves();
      expect(leaves.length).toBe(d.rooms.length); // one room per leaf
      for (const leaf of leaves) {
        expect(leaf.room).toBeDefined();
        expect(rectContains(leaf.rect, roomRect(leaf.room!))).toBe(true);
        // Respect the 2-cell margin against the leaf edges.
        const m = DEFAULT_OPTIONS.margin;
        expect(leaf.room!.x).toBeGreaterThanOrEqual(leaf.rect.x + m);
        expect(leaf.room!.y).toBeGreaterThanOrEqual(leaf.rect.y + m);
        expect(leaf.room!.x + leaf.room!.w).toBeLessThanOrEqual(leaf.rect.x + leaf.rect.w - m);
        expect(leaf.room!.y + leaf.room!.h).toBeLessThanOrEqual(leaf.rect.y + leaf.rect.h - m);
      }
    }
  });

  it("no two rooms overlap", () => {
    for (const d of dungeons.values()) {
      for (let i = 0; i < d.rooms.length; i++) {
        for (let j = i + 1; j < d.rooms.length; j++) {
          expect(overlaps(roomRect(d.rooms[i]!), roomRect(d.rooms[j]!))).toBe(false);
        }
      }
    }
  });

  it("floor graph is fully connected via flood fill", () => {
    for (const d of dungeons.values()) {
      expect(floodFillFloorCount(d)).toBe(totalFloors(d));
      expect(totalFloors(d)).toBeGreaterThan(0);
    }
  });

  it("leaf count is between 8 and 64", () => {
    for (const d of dungeons.values()) {
      const leaves = d.root.leaves().length;
      expect(leaves).toBeGreaterThanOrEqual(8);
      expect(leaves).toBeLessThanOrEqual(64);
    }
  });

  it("is deterministic per seed (identical tile-map hashes)", () => {
    for (const seed of SEEDS) {
      const a = hashTiles(generateDungeon(seed));
      const b = hashTiles(generateDungeon(seed));
      expect(a).toBe(b);
    }
  });

  it("different seeds yield different tile maps", () => {
    const hashes = SEEDS.map((s) => hashTiles(generateDungeon(s)));
    expect(new Set(hashes).size).toBe(SEEDS.length);
  });

  it("split ratio clamp keeps every leaf at least minLeafSize in each axis", () => {
    for (const d of dungeons.values()) {
      for (const leaf of d.root.leaves()) {
        expect(leaf.rect.w).toBeGreaterThanOrEqual(DEFAULT_OPTIONS.minLeafSize);
        expect(leaf.rect.h).toBeGreaterThanOrEqual(DEFAULT_OPTIONS.minLeafSize);
      }
    }
  });
});

